// Package matrix reads internal/authz/testdata/matrix.yaml, the authz
// conformance matrix (plan §5.6-3), for the Go and OpenFGA runners. The
// file is generated by docs/faz0/tarama/pairs.py; its header documents the
// fields.
//
// The reader is strict: unknown fields, duplicate keys, a second YAML
// document and references to undeclared fixtures are errors, so a change
// to the generator cannot be misread silently.
package matrix

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"regexp"
	"strings"

	"go.yaml.in/yaml/v3"
)

// Engine says where a case runs.
type Engine string

// Engines of a case.
const (
	// EngineBoth: the case runs on the Go evaluator and on OpenFGA
	// (written [go, openfga] in the file).
	EngineBoth Engine = "go+openfga"
	// EngineGoOnly: a rule outside the model (prefilter, attribute,
	// ownership, Scope); it runs only once that Go rule exists.
	EngineGoOnly Engine = "go_only"
	// EngineSkip: the case does not run (reason in the pair).
	EngineSkip Engine = "skip"
)

// UnmarshalYAML reads "go_only", "skip" or the sequence [go, openfga].
func (e *Engine) UnmarshalYAML(n *yaml.Node) error {
	var v Engine
	switch n.Kind {
	case yaml.ScalarNode:
		v = Engine(n.Value)
	case yaml.SequenceNode:
		var parts []string
		if err := n.Decode(&parts); err != nil {
			return fmt.Errorf("engine: %w", err)
		}
		v = Engine(strings.Join(parts, "+"))
	case yaml.DocumentNode, yaml.MappingNode, yaml.AliasNode:
		return fmt.Errorf("line %d: engine must be a scalar or a sequence", n.Line)
	}
	if v != EngineBoth && v != EngineGoOnly && v != EngineSkip {
		return fmt.Errorf("line %d: unknown engine %q", n.Line, v)
	}
	*e = v
	return nil
}

// Case is one row of the matrix.
type Case struct {
	ID          string   `yaml:"id"`
	Pair        string   `yaml:"pair"`
	Action      string   `yaml:"action"`  // "<type>.<action>"
	Subject     string   `yaml:"subject"` // "anonymous" or "user:<id>"
	Object      string   `yaml:"object"`  // "<type>:<id>"
	Expect      string   `yaml:"expect"`  // "allow" or "deny"
	Basis       string   `yaml:"basis"`   // key of Matrix.Basis; allow rows
	Conceal     *bool    `yaml:"conceal"` // deny rows
	Java        string   `yaml:"java"`
	JavaConceal *bool    `yaml:"java_conceal"`
	Engine      Engine   `yaml:"engine"`
	Note        string   `yaml:"note"`
	Inventory   []string `yaml:"inventory"`
	Source      []string `yaml:"source"`
}

// Allowed reports whether the expected decision is allow.
func (c *Case) Allowed() bool { return c.Expect == "allow" }

// Fixture is a declared subject or object.
type Fixture struct {
	Type  string         `yaml:"type"`
	Note  string         `yaml:"note"`
	Attrs map[string]any `yaml:"attrs"`
}

// Fixtures are the declared subjects, objects and tuples.
type Fixtures struct {
	Subjects map[string]Fixture `yaml:"subjects"`
	Objects  map[string]Fixture `yaml:"objects"`
	// Tuples are "object#relation@user".
	Tuples []string `yaml:"tuples"`
}

// Matrix is the parsed matrix.
type Matrix struct {
	Version int      `yaml:"version"`
	Status  string   `yaml:"status"`
	Engines []Engine `yaml:"engines"`
	// Basis maps a basis key to its description, which names the granting
	// relation: "atamanın işçisi (job_assignment#worker)".
	Basis map[string]string `yaml:"basis"`
	// Actions maps "<type>.<action>" to "type#relation", "Scope(...)" or
	// "go:<rule>".
	Actions  map[string]string `yaml:"actions"`
	Fixtures Fixtures          `yaml:"fixtures"`
	Cases    []Case            `yaml:"cases"`
}

// Tuples returns the fixture tuples.
func (m *Matrix) Tuples() []string { return m.Fixtures.Tuples }

// Load reads and parses the matrix file.
func Load(path string) (*Matrix, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("matrix: %w", err)
	}
	return Parse(data)
}

// Parse decodes one YAML document into a Matrix and checks it.
func Parse(data []byte) (*Matrix, error) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	dec.KnownFields(true)
	var m Matrix
	if err := dec.Decode(&m); err != nil {
		return nil, fmt.Errorf("matrix: %w", err)
	}
	var extra yaml.Node
	if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
		return nil, fmt.Errorf("matrix: the file must hold exactly one YAML document")
	}
	if err := m.check(); err != nil {
		return nil, fmt.Errorf("matrix: %w", err)
	}
	return &m, nil
}

func (m *Matrix) check() error {
	for _, set := range []map[string]Fixture{m.Fixtures.Subjects, m.Fixtures.Objects} {
		for ref, f := range set {
			if ref == "anonymous" && f.Type == "anonymous" {
				continue
			}
			if t, _, _ := strings.Cut(ref, ":"); t != f.Type {
				return fmt.Errorf("fixture %s declares type %q", ref, f.Type)
			}
		}
	}
	for _, t := range m.Fixtures.Tuples {
		if err := m.checkTuple(t); err != nil {
			return err
		}
	}
	seen := map[string]bool{}
	for i := range m.Cases {
		c := &m.Cases[i]
		if err := m.checkCase(c); err != nil {
			return fmt.Errorf("case %d (%s): %w", i, c.ID, err)
		}
		if seen[c.ID] {
			return fmt.Errorf("duplicate case %s", c.ID)
		}
		seen[c.ID] = true
	}
	return nil
}

func (m *Matrix) checkCase(c *Case) error {
	for name, v := range map[string]string{"id": c.ID, "pair": c.Pair, "action": c.Action, "subject": c.Subject, "object": c.Object} {
		if v == "" {
			return fmt.Errorf("missing %s", name)
		}
	}
	switch {
	case c.Expect != "allow" && c.Expect != "deny":
		return fmt.Errorf("expect %q", c.Expect)
	case c.Expect == "deny" && c.Conceal == nil:
		return fmt.Errorf("a deny row needs conceal")
	case c.Engine == "":
		return fmt.Errorf("missing engine")
	}
	if _, ok := m.Actions[c.Action]; !ok {
		return fmt.Errorf("action %q is not in actions", c.Action)
	}
	if _, ok := m.Basis[c.Basis]; c.Basis != "" && !ok {
		return fmt.Errorf("basis %q is not in basis", c.Basis)
	}
	if _, ok := m.Fixtures.Subjects[c.Subject]; !ok {
		return fmt.Errorf("subject %q is not a declared fixture", c.Subject)
	}
	if _, ok := m.Fixtures.Objects[c.Object]; !ok {
		return fmt.Errorf("object %q is not a declared fixture", c.Object)
	}
	return nil
}

// checkTuple checks "object#relation@user": the object is declared, and
// the user is a declared object, a declared object's userset, or a
// wildcard of a declared type.
func (m *Matrix) checkTuple(t string) error {
	objRel, user, ok := strings.Cut(t, "@")
	obj, rel, ok2 := strings.Cut(objRel, "#")
	if !ok || !ok2 || rel == "" {
		return fmt.Errorf("tuple %q: want object#relation@user", t)
	}
	if _, ok := m.Fixtures.Objects[obj]; !ok {
		return fmt.Errorf("tuple %q: object %q is not a declared fixture", t, obj)
	}
	ref, _, _ := strings.Cut(user, "#")
	if typ, id, _ := strings.Cut(ref, ":"); id == "*" {
		if !m.declaresType(typ) {
			return fmt.Errorf("tuple %q: wildcard of undeclared type %q", t, typ)
		}
		return nil
	}
	if _, ok := m.Fixtures.Objects[ref]; !ok {
		return fmt.Errorf("tuple %q: user %q is not a declared fixture", t, ref)
	}
	return nil
}

func (m *Matrix) declaresType(typ string) bool {
	for _, f := range m.Fixtures.Objects {
		if f.Type == typ {
			return true
		}
	}
	return false
}

// Relation returns the model relation of an action, or false when the
// action maps to a Go rule or a Scope.
func (m *Matrix) Relation(action string) (objectType, relation string, ok bool) {
	target := m.Actions[action]
	if strings.HasPrefix(target, "go:") || strings.HasPrefix(target, "Scope(") {
		return "", "", false
	}
	return strings.Cut(target, "#")
}

// basisRelation finds "type#relation" in a basis description.
var basisRelation = regexp.MustCompile(`[a-z_]+#[a-z_]+`)

// BasisRelation returns the relation a basis key names, "type#relation",
// or false when the description names none ("public").
func (m *Matrix) BasisRelation(key string) (string, bool) {
	rel := basisRelation.FindString(m.Basis[key])
	return rel, rel != ""
}
